export function currentFounderCheckerPredecessor(file,bytes){const row=currentFounderCheckerOps.find(x=>x.file===file);if(!row||sha(bytes)===row.before)return bytes;if(file==='scripts/check-pja-w1-blueprint-led-knowledge.mjs'&&sha(bytes)!==row.after){const physical=receivedMethodPhysicalBytes(file);assert.equal(sha(physical),row.after,'CURRENT_PJA_ANCESTOR_PHYSICAL_DRIFT');const accepted=currentFounderCheckerPredecessor(file,physical);assert.equal(sha(accepted),row.before,'CURRENT_PJA_ACCEPTED_PARENT');const raw=fs.readFileSync('content/production-closure/live-customer-commercial-convergence/final-unified-production-r1/PUBLIC-READABILITY-SOURCE-SUCCESSOR-R1.json');assert.equal(sha(raw),'572bfdaab2f94671b28a886b923ae93edb1e45ad15e5b152fbf7860d31f0ae69');const prior=JSON.parse(raw).inputs.find(x=>x.path===file);assert.equal(prior.afterSHA256,row.before,'CURRENT_PJA_READABILITY_PARENT');const ancestor=Buffer.from(prior.beforeBytesBase64,'base64');assert.equal(sha(ancestor),prior.beforeSHA256,'CURRENT_PJA_READABILITY_ANCESTOR');if(sha(bytes)===prior.beforeSHA256){assert(Buffer.from(bytes).equals(ancestor),'CURRENT_PJA_EXACT_ANCESTOR_INPUT');return bytes;}} assert.equal(sha(bytes),row.after,"CURRENT_FOUNDER_CHECKER_UNKNOWN_DELTA");let text=bytes.toString();for(const op of [...row.ops].reverse()){assert.equal(text.split(op.after).length,2,"CURRENT_FOUNDER_CHECKER_UNIQUE_INVERSE");text=text.replace(op.after,op.before);}const prior=Buffer.from(text);assert.equal(sha(prior),row.before,"CURRENT_FOUNDER_CHECKER_INVERSE");return prior;}

