export function currentTopicCoreCapacityPredecessor(file,bytes){const row=currentTopicCoreCapacityRows.find(x=>x.file===file);if(!row||sha(bytes)===row.before)return bytes;if(sha(bytes)!==row.after){const country=countryPublicGateHunks.find(x=>x.path===file);if(country&&row.before===country.afterSHA256){const physical=receivedMethodPhysicalBytes(file);assert.equal(sha(physical),row.after,'CURRENT_TOPIC_CORE_CAPACITY_PHYSICAL_DRIFT');const accepted=currentTopicCoreCapacityPredecessor(file,physical);const ancestor=currentCountryPublicGatePredecessor(file,accepted);if(sha(bytes)===sha(ancestor))return bytes;const rawAudit=fs.readFileSync('content/production-closure/live-customer-commercial-convergence/final-unified-production-r1/AUDIT-R2-PUBLIC34-RECEIVER-R2.json');assert.equal(sha(rawAudit),'f0c9c4175b2dd850e9e71ab09b200ffc9de0a98e3f49398e1a5a2463e44c7871');const audit=JSON.parse(rawAudit).paths.find(x=>x.path===file);if(audit&&audit.sha256===sha(ancestor)&&audit.previousSHA256){let prior=ancestor;for(const op of [...audit.inverse].reverse()){const after=Buffer.from(op.after,'base64'),before=Buffer.from(op.before,'base64');assert(prior.subarray(op.offset,op.offset+after.length).equals(after),'CURRENT_TOPIC_AUDIT_ANCESTOR_EXACT');prior=Buffer.concat([prior.subarray(0,op.offset),before,prior.subarray(op.offset+after.length)]);}assert.equal(sha(prior),audit.previousSHA256,'CURRENT_TOPIC_AUDIT_ANCESTOR_SHA');if(sha(bytes)===sha(prior))return bytes;}}} if(sha(bytes)!==row.after){const release=TRUSTED_RELEASE.rows.find(x=>x.path===file);if(release&&release.afterSHA256===row.before&&sha(bytes)===release.beforeSHA256){const physical=receivedMethodPhysicalBytes(file);assert.equal(sha(physical),row.after,'CURRENT_TOPIC_RELEASE_ANCESTOR_PHYSICAL_DRIFT');const accepted=currentTopicCoreCapacityPredecessor(file,physical);assert.equal(sha(accepted),release.afterSHA256,'CURRENT_TOPIC_RELEASE_ACCEPTED_PARENT');const ancestor=Buffer.from(release.beforeBytesBase64,'base64');assert.equal(sha(ancestor),release.beforeSHA256,'CURRENT_TOPIC_RELEASE_ANCESTOR_BYTES');assert(Buffer.from(bytes).equals(ancestor),'CURRENT_TOPIC_RELEASE_EXACT_INPUT');return bytes;}} assert.equal(sha(bytes),row.after,"CURRENT_TOPIC_CORE_CAPACITY_UNKNOWN_DELTA");if(row.inverse.statusOffsets){const op=row.inverse;assert.equal(op.statusOffsets.length,14,"CURRENT_TOPIC_INVENTORY_14_EXACT_FIELDS");const after=Buffer.from(op.afterToken),before=Buffer.from(op.beforeToken);let previous=bytes;for(const offset of [...op.statusOffsets].reverse()){assert(previous.subarray(offset,offset+after.length).equals(after),"CURRENT_TOPIC_INVENTORY_14_EXACT_OFFSET");previous=Buffer.concat([previous.subarray(0,offset),before,previous.subarray(offset+after.length)]);}assert.equal(sha(previous),row.before,"CURRENT_TOPIC_INVENTORY_14_FULL_ANCESTOR");return previous;} const op=row.inverse,after=Buffer.from(op.afterHex,"hex"),before=Buffer.from(op.beforeHex,"hex");assert(bytes.subarray(op.offset,op.offset+after.length).equals(after),"CURRENT_TOPIC_CORE_CAPACITY_EXACT_INVERSE");assert.equal(bytes.indexOf(after),op.offset,"CURRENT_TOPIC_CORE_CAPACITY_FIRST_INVERSE");assert.equal(bytes.indexOf(after,op.offset+1),-1,"CURRENT_TOPIC_CORE_CAPACITY_UNIQUE_INVERSE");const previous=Buffer.concat([bytes.subarray(0,op.offset),before,bytes.subarray(op.offset+after.length)]);assert.equal(sha(previous),row.before,"CURRENT_TOPIC_CORE_CAPACITY_ANCESTOR");return previous;}

// Current Owner retirement is checked against actual files and actual guards, not historical body bytes.
export async function assertCurrentThesisRetirement(){
 const retired=['thesis.html','functions/api/thesis-download.js','content/registry/thesis.json','assets/js/thesis.js','assets/js/pages/thesis.js','assets/js/pages/thesis-seven.js','assets/js/locales/en/thesis.js','assets/js/locales/zh-Hans/thesis.js'];for(const file of retired)assert(!fs.existsSync(file),'OWNER_RETIRED_TOPIC_REAPPEARED:'+file);
 const {retiredResearchTopicPath,wrapFinalReleaseWorker}=await import('../../functions/_lib/final-release-scope.js'),{onRequest}=await import('../../functions/_middleware.js');
 for(const file of ['about/index.html','research/index.html','research/why-reality-navigation/index.html']){const d=parseHTML(fs.readFileSync(file,'utf8')).document;for(const a of d.querySelectorAll('a[href],form[action]')){const href=a.getAttribute('href')||a.getAttribute('action');assert(!retiredResearchTopicPath(new URL(href,'https://www.getphios.com').pathname),'OWNER_RETIRED_TOPIC_CURRENT_LINK:'+file);}}
 for(const file of ['assets/js/public-shell.js','assets/js/knowledge/catalog.js','assets/js/pages/library.js'])assert(!new RegExp('["\x27\x60]/thesis(?:\\.html)?["\x27\x60?#/]').test(fs.readFileSync(file,'utf8')),'OWNER_RETIRED_TOPIC_CURRENT_ENTRY:'+file);
 let downstream=0;for(const route of ['/thesis','/thesis.html','/api/thesis-download']){assert(retiredResearchTopicPath(route));const request=new Request('https://qa.invalid'+route);assert.equal((await onRequest({request,env:{},next:()=>{downstream++;throw Error('OWNER_RETIRED_ROOT_DOWNSTREAM');}})).status,404);const worker=wrapFinalReleaseWorker({fetch:()=>{downstream++;throw Error('OWNER_RETIRED_FINAL_DOWNSTREAM');}},{active:true,preview:true,commit:'0'.repeat(40)});assert.equal((await worker.fetch(request,{},{})).status,404);}assert.equal(downstream,0);return {status:'OWNER_RETIRED_CURRENT_CONTRACT_PASS',filesAbsent:8,rootAndFinal404:true,historicalBodySupplied:false};
}

// Owner-approved R6 extends the existing visual inventory only. The prior
// customer assets remain byte-identical; current R6 assets retain exact
// identities and cannot grant calculation, data, paid or private access.
function currentResearchR6InventoryView(file,bytes){
 if(file!=='data/visual/approved-r2-visual-assets.json')return bytes;
 let doc;try{doc=JSON.parse(bytes)}catch{return bytes}
 const added=doc.assets.filter(a=>a.aliases.some(id=>id.startsWith('RESEARCH-R6-')));if(!added.length)return bytes;
 assert.equal(bytes.toString(),JSON.stringify(doc,null,2)+'\n','R6_INVENTORY_UNREGISTERED_ENCODING');
 const names=[...Array.from({length:8},(_,i)=>['art-'+(i+1)+'.webp','hard-'+(i+1)+'.webp','hero-'+(i+1)+'.webp']).flat(),...['access','journey','library','reading','system','visual'].map(x=>'PHIOS-'+x+'-hero.webp'),'positioning.webp'].sort();
 assert.deepEqual(added.map(a=>a.r2Path.split('/').at(-1)).sort(),names,'R6_EXACT_31_IDENTITIES');
 assert.equal(new Set(added.map(a=>a.r2Path)).size,31,'R6_DUPLICATE_VISUAL');
 const fields=new Set(['canonicalFilename','r2Path','semanticName','family','role','aliases','sources','intendedRoutes','desktopPresentation','mobilePresentation','status','boundConsumers','visibility','width','height','remoteProof','unusedReason']);
 for(const a of added){const name=a.r2Path.split('/').at(-1);assert(Object.keys(a).every(k=>fields.has(k)),'R6_UNREGISTERED_DATA_FIELD');assert.equal(a.r2Path,'images/research/r6/'+name);assert.equal(a.canonicalFilename,'RESEARCH-R6-'+name);assert.deepEqual(a.aliases,['RESEARCH-R6-'+name.slice(0,-5).toUpperCase()]);assert.equal(a.role,'PUBLIC_EDITORIAL_VISUAL');assert.deepEqual(a.intendedRoutes,['/research/']);assert.deepEqual(a.boundConsumers,['assets/js/pages/research-r6.js']);assert.equal(a.visibility,'public');assert.equal(a.remoteProof.httpStatus,200);assert.equal(a.remoteProof.contentType,'image/webp');assert(/^[a-f0-9]{64}$/.test(a.remoteProof.sha256));assert(a.width>0&&a.height>0);}
 const prior={...doc,assets:doc.assets.filter(a=>!added.includes(a))},view=Buffer.from(JSON.stringify(prior,null,2)+'\n');
 assert.equal(sha(view),'ff1b9ce2715a523d55691feaee6993af321459068513a4c31e73899948c9baa7','R6_PRIOR_VISUAL_CONSUMERS_CHANGED');
 return view;
}

